30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "postcode")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    @Email
59	    private String email;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    public String getAddress() {
92	        return this.address;
93	    }
94	
95	    public void setAddress(String address) {
96	        this.address = address;
97	    }
98	
99	    public String getCity() {
100	        return this.city;
101	    }
102	
103	    public void setCity(String city) {
104	        this.city = city;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = telephone;
121	    }
122	
123	    public String getEmail() {
124	        return this.email;
125	    }
126	
127	    public void setEmail(String email) {
128	        this.email = email == null ? null : email.toLowerCase();
129	    }
130	
131	    public LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    public LocalDate getBirthDate() {
140	        return this.birthDate;
141	    }
142	
143	    public void setBirthDate(LocalDate birthDate) {
144	        this.birthDate = birthDate;
145	    }
146	
147	    /**
148	     * The owner's age band derived from {@link #birthDate} relative to the
149	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
150	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
151	     * is the number of complete years between the birthDate and the registrationDate (or the
152	     * current date when the registrationDate is not yet set).
153	     */
154	    public String getAgeBand() {
155	        if (this.birthDate == null) {
156	            return null;
157	        }
158	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
159	        int years = Period.between(this.birthDate, reference).getYears();
160	        if (years < 18) {
161	            return "MINOR";
162	        }
163	        if (years < 65) {
164	            return "ADULT";
165	        }
166	        return "SENIOR";
167	    }
168	
169	    public String getCustomerCode() {
170	        return this.customerCode;
171	    }
172	
173	    public void setCustomerCode(String customerCode) {
174	        this.customerCode = customerCode;
175	    }
176	
177	    public String getHouseholdId() {
178	        return this.householdId;
179	    }
180	
181	    public void setHouseholdId(String householdId) {
182	        this.householdId = householdId;
183	    }
184	
185	    public Integer getNamesakeCount() {
186	        return this.namesakeCount;
187	    }
188	
189	    public void setNamesakeCount(Integer namesakeCount) {
190	        this.namesakeCount = namesakeCount;
191	    }
192	
193	    public Boolean getBulkSignupWarning() {
194	        return this.bulkSignupWarning;
195	    }
196	
197	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
198	        this.bulkSignupWarning = bulkSignupWarning;
199	    }
200	
201	    public Integer getHouseholdSize() {
202	        return this.householdSize;
203	    }
204	
205	    public void setHouseholdSize(Integer householdSize) {
206	        this.householdSize = householdSize;
207	    }
208	
209	    public Boolean getPossibleDuplicate() {
210	        return this.possibleDuplicate;
211	    }
212	
213	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
214	        this.possibleDuplicate = possibleDuplicate;
215	    }
216	
217	    public Integer getPossibleDuplicateOf() {
218	        return this.possibleDuplicateOf;
219	    }
220	
221	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
222	        this.possibleDuplicateOf = possibleDuplicateOf;
223	    }
224	
225	    /**
226	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
227	     */
228	    public String getDisplayName() {
229	        return this.getLastName() + ", " + this.getFirstName();
230	    }
231	
232	    /**
233	     * The owner's initials: the upper-cased first letters of firstName and lastName,
234	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
235	     */
236	    public String getInitials() {
237	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
238	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
239	    }
240	
241	    /**
242	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
243	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
244	     */
245	    public String getMembershipNumber() {
246	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
247	    }
248	
249	    /**
250	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
251	     * contained in the owner's {@link #customerCode}.
252	     */
253	    public int getCheckDigit() {
254	        return luhnCheckDigit(this.customerCode);
255	    }
256	
257	    /**
258	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
259	     * contained in {@code value}. Reading the digits right to left, every second one is
260	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
261	     * digits are summed, and the check digit is the amount that must be added to that sum to
262	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
263	     * the digit is taken over exactly the digits the string carries.
264	     */
265	    private static int luhnCheckDigit(String value) {
266	        int sum = 0;
267	        boolean doubling = true;
268	        for (int i = value.length() - 1; i >= 0; i--) {
269	            char c = value.charAt(i);
270	            if (c < '0' || c > '9') {
271	                continue;
272	            }
273	            int digit = c - '0';
274	            if (doubling) {
275	                digit *= 2;
276	                if (digit > 9) {
277	                    digit -= 9;
278	                }
279	            }
280	            sum += digit;
281	            doubling = !doubling;
282	        }
283	        return (10 - (sum % 10)) % 10;
284	    }
285	
286	    /** Fixed city-to-region table used to derive an owner's locality. */
287	    private static final Map<String, String> CITY_REGION = Map.of(
288	        "Sydney", "NSW",
289	        "Melbourne", "VIC",
290	        "Brisbane", "QLD");
291	
292	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
293	    public static final String UNKNOWN_REGION = "UNKNOWN";
294	
295	    /**
296	     * The canonical region for a city, derived from the fixed city-to-region table
297	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
298	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
299	     * source of the city-to-region mapping, shared by every rule that is keyed by
300	     * region so the mapping is never re-derived elsewhere.
301	     */
302	    public static String regionOf(String city) {
303	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
304	    }
305	
306	    /**
307	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
308	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
309	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
310	     * known region). Locality is read from the region-and-hash identity so it never re-derives
311	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
312	     */
313	    public String getLocality() {
314	        if (this.customerCode == null) {
315	            return UNKNOWN_REGION;
316	        }
317	        int dash = this.customerCode.indexOf('-');
318	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
319	    }
320	
321	    /**
322	     * The region derived from this owner's postcode alone: the region whose fixed
323	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
324	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
325	     * component built into the owner's customer code at creation and, through it, the source of the
326	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
327	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
328	     */
329	    public String getRegion() {
330	        return regionOfPostcode(this.postcode);
331	    }
332	
333	    /**
334	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
335	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
336	     * no known range.
337	     */
338	    private static String regionOfPostcode(String postcode) {
339	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
340	            return null;
341	        }
342	        int value = Integer.parseInt(postcode);
343	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
344	            int[] range = entry.getValue();
345	            if (value >= range[0] && value <= range[1]) {
346	                return entry.getKey();
347	            }
348	        }
349	        return null;
350	    }
351	
352	    /**
353	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
354	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
355	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
356	     */
357	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
358	        "NSW", new int[] {2000, 2099},
359	        "VIC", new int[] {3000, 3099},
360	        "QLD", new int[] {4000, 4099});
361	
362	    /**
363	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
364	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
365	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
366	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
367	     * city with no known region accepts any 4-digit postcode.
368	     */
369	    public boolean isPostcodeValid() {
370	        if (this.postcode == null) {
371	            return true;
372	        }
373	        if (!this.postcode.matches("[0-9]{4}")) {
374	            return false;
375	        }
376	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
377	        if (range == null) {
378	            return true;
379	        }
380	        int value = Integer.parseInt(this.postcode);
381	        return value >= range[0] && value <= range[1];
382	    }
383	
384	    /**
385	     * The national (subscriber) digit count required by each known country calling code, keyed by
386	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
387	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
388	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
389	     * re-derived elsewhere.
390	     */
391	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
392	        "1", 10,
393	        "61", 9);
394	
395	    /**
396	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
397	     * E.164 digit string, choosing the longest matching code known to
398	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
399	     * country code. This is the single place a country code is read from an E.164 number, so every
400	     * rule keyed by that code shares one derivation.
401	     */
402	    private static String countryCodeOf(String e164Digits) {
403	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
404	            .filter(e164Digits::startsWith)
405	            .max(Comparator.comparingInt(String::length))
406	            .orElse(null);
407	    }
408	
409	    /**
410	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
411	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
412	     * known code wins; a number whose country code is not recognised passes this check (its length is
413	     * then governed only by the general E.164 bound), while a recognised code must be followed by
414	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
415	     */
416	    public static boolean hasValidNationalLength(String e164Digits) {
417	        String countryCode = countryCodeOf(e164Digits);
418	        if (countryCode == null) {
419	            return true;
420	        }
421	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
422	    }
423	
424	    /**
425	     * The owner's membership level, a number from 1 to 4: it starts at 1, gains 1 when an email is
426	     * present, gains 1 when namesakeCount is 0, and gains 1 when the owner's {@linkplain #getTenureDays()
427	     * tenure} exceeds 365 days. The email and namesake factors are the only ones available on creation,
428	     * so a newly created owner (zero tenure) never exceeds level 3; level 4 is reached only once tenure
429	     * grows beyond 365 days.
430	     */
431	    public Integer getMembershipLevel() {
432	        int level = 1;
433	        if (this.email != null && !this.email.isEmpty()) {
434	            level++;
435	        }
436	        if (this.namesakeCount != null && this.namesakeCount == 0) {
437	            level++;
438	        }
439	        if (this.getTenureDays() > 365) {
440	            level++;
441	        }
442	        return level;
443	    }
444	
445	    /**
446	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
447	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
448	     * zero tenure). Never negative.
449	     */
450	    public long getTenureDays() {
451	        if (this.registrationDate == null) {
452	            return 0;
453	        }
454	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
455	    }
456	
457	    /**
458	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
459	     * otherwise {@code 'PHONE'}.
460	     */
461	    public String getContactPreference() {
462	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
463	    }
464	
465	    /**
466	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
467	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
468	     * the national digits grouped into threes from the left separated by spaces,
469	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
470	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
471	     * E.164 form, or carries no known country code.
472	     */
473	    public String getTelephoneDisplay() {
474	        if (this.telephone == null || !this.telephone.startsWith("+")) {
475	            return this.telephone;
476	        }
477	        String digits = this.telephone.substring(1);
478	        String countryCode = countryCodeOf(digits);
479	        if (countryCode == null) {
480	            return this.telephone;
481	        }
482	        String national = digits.substring(countryCode.length());
483	        StringBuilder groups = new StringBuilder();
484	        for (int i = 0; i < national.length(); i += 3) {
485	            if (groups.length() > 0) {
486	                groups.append(' ');
487	            }
488	            groups.append(national, i, Math.min(i + 3, national.length()));
489	        }
490	        return "+" + countryCode + " " + groups;
491	    }
492	
493	    /**
494	     * The owner's identity key: the single derived value used for duplicate detection.
495	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
496	     * empty string when absent) and the householdId (or the empty string when the owner
497	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
498	     * Two owners are duplicates only when their whole identity keys are equal.
499	     */
500	    public String getIdentityKey() {
501	        String telephonePart = this.telephone == null ? "" : this.telephone;
502	        String emailPart = this.email == null ? "" : this.email;
503	        String householdPart = this.householdId == null ? "" : this.householdId;
504	        return telephonePart + "|" + emailPart + "|" + householdPart;
505	    }
506	
507	    protected Set<Pet> getPetsInternal() {
508	        if (this.pets == null) {
509	            this.pets = new HashSet<>();
510	        }
511	        return this.pets;
512	    }
513	
514	    protected void setPetsInternal(Set<Pet> pets) {
515	        this.pets = pets;
516	    }
517	
518	    public List<Pet> getPets() {
519	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
520	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
521	        return Collections.unmodifiableList(sortedPets);
522	    }
523	
524	    public void setPets(List<Pet> pets) {
525	        this.pets = new HashSet<>(pets);
526	    }
527	
528	    public void addPet(Pet pet) {
529	        getPetsInternal().add(pet);
530	        pet.setOwner(this);
531	    }
532	
533	    /**
534	     * Return the Pet with the given name, or null if none found for this Owner.
535	     *
536	     * @param name to test
537	     * @return true if pet name is already in use
538	     */
539	    public Pet getPet(String name) {
540	        return getPet(name, false);
541	    }
542	
543	    /**
544	     * Return the Pet with the given name, or null if none found for this Owner.
545	     *
546	     * @param name to test
547	     * @return true if pet name is already in use
548	     */
549	    public Pet getPet(String name, boolean ignoreNew) {
550	        name = name.toLowerCase();
551	        for (Pet pet : getPetsInternal()) {
552	            if (!ignoreNew || !pet.isNew()) {
553	                String compName = pet.getName();
554	                compName = compName.toLowerCase();
555	                if (compName.equals(name)) {
556	                    return pet;
557	                }
558	            }
559	        }
560	        return null;
561	    }
562	
563	    public Pet getPet(Integer petId) {
564	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
565	    }
566	
567	    @Override
568	    public String toString() {
569	        return new ToStringCreator(this)
570	
571	            .append("id", this.getId())
572	            .append("new", this.isNew())
573	            .append("lastName", this.getLastName())
574	            .append("firstName", this.getFirstName())
575	            .append("address", this.address)
576	            .append("city", this.city)
577	            .append("telephone", this.telephone)
578	            .append("email", this.email)
579	            .toString();
580	    }
581	}
